create table eba_demo_appr_vacation (
    id              number
        generated by default on null as identity
    not null enable,
    original_user   varchar2(30 char),
    substitute_user varchar2(30 char),
    start_date      date,
    end_date        date,
    reason          varchar2(80 byte),
    task_def_ids    varchar2(80 byte) not null enable
);

alter table eba_demo_appr_vacation
    add constraint eba_demo_appr_vacation_id_pk primary key ( id )
        using index enable;


